<script>
(function(){
"use strict";
var NS="http://www.w3.org/2000/svg";
var codeLines=[
"public static BST buildBalanced(int[] keys) {",
"    BST t = new BST();",
"    t.root = build(keys, 0, keys.length - 1, null);",
"    return t;",
"}",
"private static Node build(int[] keys, int low, int high, Node parent) {",
"    if (low > high) return null;",
"    int mid = low + (high - low) / 2;",
"    Node x = new Node(keys[mid]);",
"    x.p = parent;",
"    x.left = build(keys, low, mid - 1, x);",
"    x.right = build(keys, mid + 1, high, x);",
"    return x;",
"}"
];
var code=document.getElementById("code");
var codeRows=codeLines.map(function(line,i){
 var row=document.createElement("span"),no=document.createElement("span"),source=document.createElement("span");
 row.className="source-line";no.className="line-no";no.textContent=String(i+1);
 source.textContent=line;row.append(no,source);code.appendChild(row);return row;
});
var keys=[],frames=[],nodes=[],index=0;
function snap(line,title,description,low,high,mid,active,extra){
 frames.push({line:line,title:title,description:description,low:low,high:high,mid:mid,active:active,extra:extra,
  nodes:nodes.map(function(n){return {key:n.key,x:n.x,y:n.y,p:n.p,left:n.left,right:n.right}})});
}
function walk(low,high,parent,areaLeft,areaRight,depth){
 var parentKey=parent?parent.key:null;
 snap(6,"Call build("+low+", "+high+", "+(parentKey===null?"null":parentKey)+")","A recursive call starts. Check the range before creating a Node.",low,high,null,parentKey,"Parent = "+(parentKey===null?"null":parentKey));
 if(low>high){
  snap(7,"Empty range → return null","There is no key in this subarray. No Node is created; the caller receives null.",low,high,null,parentKey,"Base case");
  return null;
 }
 var mid=low+Math.floor((high-low)/2);
 snap(8,"Compute the lower middle","For even length, integer division selects the left/lower of the two middle positions.",low,high,mid,parentKey,"mid = "+mid+", keys[mid] = "+keys[mid]);
 var n={key:keys[mid],x:(areaLeft+areaRight)/2,y:77+depth*106,p:null,left:null,right:null};
 nodes.push(n);
 snap(9,"Create Node "+n.key,"new Node(keys[mid]) constructs one Node. It is not a new BST object.",low,high,mid,n.key,"x.key = "+n.key);
 n.p=parentKey;
 snap(10,"Set "+n.key+".p","Store the parent reference. The parent's left/right reference may still be pending until its recursive call returns.",low,high,mid,n.key,"x.p = "+(parentKey===null?"null":parentKey));
 snap(11,"Recurse to left half","The caller waits while build processes keys[low .. mid - 1].",low,high,mid,n.key,"Left range: ["+low+", "+(mid-1)+"]");
 var left=walk(low,mid-1,n,areaLeft,n.x-4,depth+1);
 n.left=left?left.key:null;
 snap(11,"Assign "+n.key+".left","The returned Node (or null) becomes the left child of "+n.key+".",low,high,mid,n.key,"x.left = "+(n.left===null?"null":n.left));
 snap(12,"Recurse to right half","The caller waits while build processes keys[mid + 1 .. high].",low,high,mid,n.key,"Right range: ["+(mid+1)+", "+high+"]");
 var right=walk(mid+1,high,n,n.x+4,areaRight,depth+1);
